#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_SLIMES 100000
#define MAX_GRID 1000000

typedef struct {
    int x, y;
} Point;

typedef struct {
    int u, v;
    int dist;
} Edge;

Point slimes[MAX_SLIMES];
int slime_count = 0;
int parent[MAX_SLIMES];
int rank[MAX_SLIMES];
Edge edges[MAX_SLIMES * 4]; // Maximum possible edges
int edge_count = 0;

int compare_edges(const void *a, const void *b) {
    return ((Edge*)a)->dist - ((Edge*)b)->dist;
}

int find(int x) {
    if (parent[x] != x)
        parent[x] = find(parent[x]);
    return parent[x];
}

void union_sets(int x, int y) {
    int px = find(x), py = find(y);
    if (px == py) return;
    if (rank[px] < rank[py])
        parent[px] = py;
    else if (rank[px] > rank[py])
        parent[py] = px;
    else {
        parent[py] = px;
        rank[px]++;
    }
}

int manhattan_distance(Point a, Point b) {
    return abs(a.x - b.x) + abs(a.y - b.y);
}

int main() {
    int W, H;
    scanf("%d %d", &W, &H);

    // Initialize parent and rank arrays
    for (int i = 0; i < MAX_SLIMES; i++) {
        parent[i] = i;
        rank[i] = 0;
    }

    // Read grid and find slimes
    char line[MAX_GRID + 2];
    for (int y = 0; y < H; y++) {
        scanf("%s", line);
        for (int x = 0; x < W; x++) {
            if (line[x] == 'S') {
                slimes[slime_count].x = x;
                slimes[slime_count].y = y;
                slime_count++;
            }
        }
    }

    // If there's only 1 or 0 slimes, no moves needed
    if (slime_count <= 1) {
        printf("0\n");
        return 0;
    }

    // Create edges between all pairs of slimes
    for (int i = 0; i < slime_count; i++) {
        for (int j = i + 1; j < slime_count; j++) {
            edges[edge_count].u = i;
            edges[edge_count].v = j;
            edges[edge_count].dist = manhattan_distance(slimes[i], slimes[j]);
            edge_count++;
        }
    }

    // Sort edges by distance
    qsort(edges, edge_count, sizeof(Edge), compare_edges);

    // Kruskal's algorithm to find MST
    long long total_moves = 0;
    int edges_used = 0;

    for (int i = 0; i < edge_count && edges_used < slime_count - 1; i++) {
        int u = edges[i].u;
        int v = edges[i].v;

        if (find(u) != find(v)) {
            union_sets(u, v);
            total_moves += edges[i].dist;
            edges_used++;
        }
    }

    printf("%lld\n", total_moves);

    return 0;
}

