int main(void) {
    int W, H, N;
    if (scanf("%d %d %d", &W, &H, &N) != 3) return 0;

    Point *p = (Point *)malloc(sizeof(Point) * N);
    for (int i = 0; i < N; i++) {
        scanf("%d %d", &p[i].x, &p[i].y);
    }

    if (N <= 1) {
        printf("0\n");
        free(p);
        return 0;
    }

    int FULL = 1 << N;

    /* can[i][j] = 1 if slime i can unite with slime j in one move
       when only these two matter, i.e. they are in the same row/column. */
    char *can = (char *)calloc(N * N, sizeof(char));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (i == j) continue;
            if (p[i].x == p[j].x || p[i].y == p[j].y) {
                can[i * N + j] = 1;
            }
        }
    }

    /* conn[mask] = whether all slimes in mask can be merged into one slime
       without using any slime outside mask. */
    char *conn = (char *)calloc(FULL, sizeof(char));
    for (int i = 0; i < N; i++) conn[1 << i] = 1;

    for (int mask = 1; mask < FULL; mask++) {
        if (conn[mask]) continue;
        int sub = (mask - 1) & mask;
        while (sub) {
            int other = mask ^ sub;
            if (conn[sub] && conn[other]) {
                int ok = 0;
                for (int i = 0; i < N && !ok; i++) if (sub & (1 << i)) {
                    for (int j = 0; j < N; j++) if (other & (1 << j)) {
                        if (can[i * N + j]) {
                            ok = 1;
                            break;
                        }
                    }
                }
                if (ok) {
                    conn[mask] = 1;
                    break;
                }
            }
            sub = (sub - 1) & mask;
        }
    }

    /* dp[mask] = minimum moves to merge all slimes in mask into one slime. */
    int *dp = (int *)malloc(sizeof(int) * FULL);
    for (int mask = 0; mask < FULL; mask++) dp[mask] = INF;
    for (int i = 0; i < N; i++) dp[1 << i] = 0;

    for (int mask = 1; mask < FULL; mask++) {
        if (!conn[mask]) continue;
        if ((mask & (mask - 1)) == 0) continue; /* single slime */

        int sub = (mask - 1) & mask;
        while (sub) {
            int other = mask ^ sub;
            if (other && conn[sub] && conn[other]) {
                int ok = 0;
                for (int i = 0; i < N && !ok; i++) if (sub & (1 << i)) {
                    for (int j = 0; j < N; j++) if (other & (1 << j)) {
                        if (can[i * N + j]) {
                            ok = 1;
                            break;
                        }
                    }
                }
                if (ok) {
                    dp[mask] = min_int(dp[mask], dp[sub] + dp[other] + 1);
                }
            }
            sub = (sub - 1) & mask;
        }
    }

    printf("%d\n", dp[FULL - 1]);

    free(p);
    free(can);
    free(conn);
    free(dp);
    return 0;
}

