        TreeSet<Integer> startSet = new TreeSet<>();
        for (int[] p : initial) startSet.add(p[0] * 100 + p[1]);

        Map<String, Integer> dist = new HashMap<>();
        Queue<TreeSet<Integer>> queue = new LinkedList<>();
        String startKey = startSet.toString();
        dist.put(startKey, 0);
        queue.add(startSet);

        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};

        while (!queue.isEmpty()) {
            TreeSet<Integer> cur = queue.poll();
            int d = dist.get(cur.toString());
            if (cur.size() == 1) { System.out.println(d); return; }

            List<Integer> slimes = new ArrayList<>(cur);
            for (int i = 0; i < slimes.size(); i++) {
