public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Point {
        int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    static int W, H, N;
    static Point[] p;
    static int[][] dist;
    static int FULL;
    static int[][] memo;

    static int solve(int mask, int root) {
        if (memo[mask][root] != -1) return memo[mask][root];
        if ((mask & (mask - 1)) == 0) return memo[mask][root] = 0; // single slime

        int best = Integer.MAX_VALUE / 4;

        int sub = (mask - 1) & mask;
        while (sub > 0) {
            if ((sub & (1 << root)) != 0 && sub != mask) {
                int other = mask ^ sub;
                for (int j = 0; j < N; j++) {
                    if ((other & (1 << j)) == 0) continue;
                    int cand = solve(sub, root) + solve(other, j) + dist[root][j];
                    if (cand < best) best = cand;
                }
            }
            sub = (sub - 1) & mask;
        }

        return memo[mask][root] = best;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        W = fs.nextInt();
        H = fs.nextInt();
        N = fs.nextInt();

        p = new Point[N];
        for (int i = 0; i < N; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            p[i] = new Point(x, y);
        }

        dist = new int[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (i == j) dist[i][j] = 0;
                else {
                    int dx = Math.abs(p[i].x - p[j].x);
                    int dy = Math.abs(p[i].y - p[j].y);
                    // Minimum moves for one slime/group at i to reach slime/group at j:
                    // 1 if same row/column, else 2.
                    dist[i][j] = (dx == 0 || dy == 0) ? 1 : 2;
                }
            }
        }

        FULL = 1 << N;
        memo = new int[FULL][N];
        for (int i = 0; i < FULL; i++) Arrays.fill(memo[i], -1);

        int ans = Integer.MAX_VALUE / 4;
        int all = FULL - 1;
        for (int root = 0; root < N; root++) {
            ans = Math.min(ans, solve(all, root));
        }

        System.out.println(ans);
    }
}

