int main() {
    while (cin >> W >> H && (W || H)) {
        int N; // number of slimes - read grid
        vector<string> grid(H);
        for (int i = 0; i < H; i++) cin >> grid[i];

        vector<pair<int,int>> init_slimes;
        for (int i = 0; i < H; i++)
            for (int j = 0; j < W; j++)
                if (grid[i][j] == 'o') init_slimes.push_back({i, j});

        // BFS
        // State: sorted vector of positions encoded
        auto encode = [&](vector<pair<int,int>>& v) {
            string s;
            for (auto& p : v) { s += (char)p.first; s += (char)p.second; s += ','; }
            return s;
        };

        vector<pair<int,int>> start = init_slimes;
        sort(start.begin(), start.end());

        map<string, int> dist;
        queue<vector<pair<int,int>>> q;
        q.push(start);
        dist[encode(start)] = 0;

        int dx[] = {0,0,1,-1};
        int dy[] = {1,-1,0,0};

        while (!q.empty()) {
            auto cur = q.front(); q.pop();
            string cs = encode(cur);
            int d = dist[cs];

            if (cur.size() == 1) { cout << d << "\n"; goto done; }

            set<pair<int,int>> pos(cur.begin(), cur.end());

            for (int i = 0; i < (int)cur.size(); i++) {
                for (int dir = 0; dir < 4; dir++) {
                    int r = cur[i].first, c = cur[i].second;
                    while (true) {
                        int nr = r + dx[dir], nc = c + dy[dir];
                        if (nr < 0 || nr >= H || nc < 0 || nc >= W) break; // hit wall
                        if (pos.count({nr, nc})) { r = nr; c = nc; break; } // hit slime
                        r = nr; c = nc;
                    }
                    if (r == cur[i].first && c == cur[i].second) continue; // no move

                    vector<pair<int,int>> next;
                    for (int j = 0; j < (int)cur.size(); j++)
                        if (j != i) next.push_back(cur[j]);
                    // remove duplicate at (r,c) if exists, add (r,c)
                    next.erase(remove(next.begin(), next.end(), make_pair(r,c)), next.end());
                    next.push_back({r, c});
                    sort(next.begin(), next.end());

                    string ns = encode(next);
                    if (!dist.count(ns)) {
                        dist[ns] = d + 1;
                        q.push(next);
                    }
                }
            }
        }
        done:;
    }
}

