struct StateHash {
    size_t operator()(const vector<int>& v) const noexcept {
        size_t h = 1469598103934665603ULL;
        for (int x : v) {
            h ^= (size_t)x + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2);
        }
        return h;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int W, H;
    cin >> W >> H;
    vector<string> g(H);
    for (int y = 0; y < H; ++y) cin >> g[y];

    vector<pair<int,int>> initPos;
    for (int y = 0; y < H; ++y) {
        for (int x = 0; x < W; ++x) {
            if (g[y][x] == '*') initPos.push_back({x, y});
        }
    }

    int N = (int)initPos.size();
    if (N <= 1) {
        cout << 0 << '\n';
        return 0;
    }

    auto id = [W](int x, int y) { return y * W + x; };
    auto xy = [W](int p) { return pair<int,int>{p % W, p / W}; };

    vector<int> start;
    for (auto &p : initPos) start.push_back(id(p.first, p.second));
    sort(start.begin(), start.end());

    queue<vector<int>> q;
    unordered_map<vector<int>, int, StateHash> dist;

    dist[start] = 0;
    q.push(start);

    const int dx[4] = {1, -1, 0, 0};
    const int dy[4] = {0, 0, 1, -1};

    while (!q.empty()) {
        vector<int> cur = q.front();
        q.pop();
        int d = dist[cur];

        if ((int)cur.size() == 1) {
            cout << d << '\n';
            return 0;
        }

        unordered_set<int> occ(cur.begin(), cur.end());

        for (int i = 0; i < (int)cur.size(); ++i) {
            int p = cur[i];
            auto [x, y] = xy(p);

            for (int dir = 0; dir < 4; ++dir) {
                int nx = x, ny = y;

                while (true) {
                    int tx = nx + dx[dir];
                    int ty = ny + dy[dir];

                    if (tx < 0 || tx >= W || ty < 0 || ty >= H) break; // wall
                    int tid = id(tx, ty);

                    if (occ.count(tid)) { // enters another slime cell -> merge
                        vector<int> nxt;
                        for (int j = 0; j < (int)cur.size(); ++j) {
                            if (j == i) continue;
                            if (cur[j] == tid) continue;
                            nxt.push_back(cur[j]);
                        }
                        nxt.push_back(tid);
                        sort(nxt.begin(), nxt.end());
                        if (!dist.count(nxt)) {
                            dist[nxt] = d + 1;
                            q.push(nxt);
                        }
                        break;
                    }

                    nx = tx;
                    ny = ty;
                }
            }
        }
    }

    return 0;
}

import sys

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return False
        if self.rank[rx] < self.rank[ry]:
            self.parent[rx] = ry
        elif self.rank[rx] > self.rank[ry]:
            self.parent[ry] = rx
        else:
            self.parent[ry] = rx
            self.rank[rx] += 1
        return True

def solve():
    input_data = sys.stdin.read().strip().splitlines()
    if not input_data:
        return
    H, W = map(int, input_data[0].split())
    slimes = []
    for i in range(1, H+1):
        row = input_data[i]
        for j, ch in enumerate(row):
            if ch == '*':
                slimes.append((i-1, j))  # 0-based coordinates

    n = len(slimes)
    if n <= 1:
        print(0)
        return

    edges = []

    # Sort by x then y
    idx_sorted = sorted(range(n), key=lambda i: (slimes[i][0], slimes[i][1]))
    for k in range(n-1):
        i1, i2 = idx_sorted[k], idx_sorted[k+1]
        x1, y1 = slimes[i1]
        x2, y2 = slimes[i2]
        dist = abs(x1-x2) + abs(y1-y2)
        edges.append((dist, i1, i2))

    # Sort by y then x
    idx_sorted = sorted(range(n), key=lambda i: (slimes[i][1], slimes[i][0]))
    for k in range(n-1):
        i1, i2 = idx_sorted[k], idx_sorted[k+1]
        x1, y1 = slimes[i1]
        x2, y2 = slimes[i2]
        dist = abs(x1-x2) + abs(y1-y2)
        edges.append((dist, i1, i2))

    edges.sort()
    dsu = DSU(n)
    total_cost = 0
    edges_used = 0
    for cost, u, v in edges:
        if dsu.union(u, v):
            total_cost += cost
            edges_used += 1
            if edges_used == n-1:
                break

    print(total_cost)

